  "prediction_basis_card_ids": ["C01", "C06", "C43", "C46", "C21", "C44", "C82", "C213", "C255", "C287", "C282"],
  "claims": [
    {
      "claim": "The most transferable direct gold outcomes for the quaternary ammonium query are ipratropium (absolute oral F ≈2–3.3% in healthy volunteers across 2–20 mg) and physostigmine (F ≈1–8% in healthy volunteers), both below the 20% threshold.",
      "card_ids": ["C01", "C06", "C43", "C46", "C21", "C44", "C82"]
    },
    {
      "claim": "L5 gut-wall evidence shows quaternary ammonium cations can undergo intestinal secretion/transport: N-methylscopolamine is secreted from blood into intestinal lumen and ipratropium is an OCTN2 substrate, supporting presystemic loss for the charged query.",
      "card_ids": ["C213", "C255"]
    },
    {
      "claim": "L6 hepatic-clearance evidence is directionally consistent with low F: ajmaline, the parent scaffold, shows a rate-dependent hepatic extraction ratio in rats; physostigmine has a liver half-life of 28 min in rats; and even quaternary N-methylscopolamine shows some CYP1A2-mediated metabolism in human liver microsomes.",
      "card_ids": ["C287", "C282", "C269"]
    },
    {
      "claim": "Higher-F outliers (ipratropium 32% in one study; physostigmine 25.3% in surgical patients) and rat intestinal absorption of ajmaline do not overturn the low prediction because they are less transferable or not threshold-relevant for the quaternary query.",
      "card_ids": ["C15", "C45", "C161"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C287", "C282", "C269"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule (N-propyl quaternary ajmaline derivative).",
    "L6 hepatic-clearance records are for ajmaline, physostigmine, and N-methylscopolamine, not the query; quaternary modification may alter hepatic extraction and metabolism.",
    "The explicit quaternary ammonium in the SMILES conflicts with the property-tool neutral fraction of 0.98; permanent charge is a major absorption liability but its quantitative impact on this lipophilic scaffold is unknown.",
    "No query-specific permeability, efflux, intestinal metabolism, or hepatic clearance data.",
    "Higher-F outliers in less transferable contexts (ipratropium 32%, physostigmine 25.3%) create uncertainty around the threshold."
  ],
  "decision_summary": "Predicted low: the query is a permanently charged N-propyl quaternary ajmaline derivative; the most transferable direct gold contexts (ipratropium F ≈2–3.3%, physostigmine F ≈1–8% in healthy volunteers) indicate F <20%, L5 gut-wall secretion/transport of quaternary ammonium cations supports presystemic loss, and L6 hepatic-clearance evidence (ajmaline hepatic extraction, physostigmine liver metabolism, minor NMS CYP metabolism) is directionally consistent. Higher-F outliers and rat ajmaline absorption do not overturn this because they are less transferable or not threshold-relevant."
}

